package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.planner.*;import io.aetheris.orchestrator.policy.OperationMode;import org.springframework.web.bind.annotation.*;import java.util.UUID;@RestController @RequestMapping("/api/orchestrator/stage8/missions") public class MissionPlanProposalController {private final MissionPlanProposalService service;public MissionPlanProposalController(MissionPlanProposalService service){this.service=service;}@PostMapping("/{missionId}/propose") public MissionPlanProposalResult propose(@PathVariable UUID missionId,@RequestBody MissionPlanProposalRequest r){return service.propose(missionId,r);}@PostMapping("/{missionId}/validate") public MissionPlanProposalResult validate(@PathVariable UUID missionId,@RequestParam(defaultValue="BALANCED") OperationMode mode,@RequestParam(defaultValue="false") boolean materialize,@RequestBody String raw){return service.validateRaw(missionId,raw,mode,materialize);}}
